#!/usr/bin/env node
// Build a Screaming Frog `.dbseospider` fixture from Coqui's committed reference
// CSVs, so the import/sync tests and demo use the same URL set as the parity
// harness.
//
// Usage:
//   node tools/parity/make-sf-fixture.mjs [urls.csv] [links.csv] [out.dbseospider]
//
// Defaults to tools/parity/fixtures/reference/{urls,links}.csv and writes
// tools/parity/fixtures/reference/reference.dbseospider. The real reference
// export can be regenerated by pointing the first two arguments at its CSVs.
//
// Requires Node 22.5+ (node:sqlite) and the `zip` CLI.

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { spawnSync } from 'node:child_process';

const ROOT = path.resolve(import.meta.dirname, '../..');
const args = process.argv.slice(2);
const urlsCsv = path.resolve(args[0] ?? path.join(ROOT, 'tools/parity/fixtures/reference/urls.csv'));
const linksCsv = path.resolve(args[1] ?? path.join(ROOT, 'tools/parity/fixtures/reference/links.csv'));
const out = path.resolve(args[2] ?? path.join(ROOT, 'tools/parity/fixtures/reference/reference.dbseospider'));

function parseCsv(file) {
  const text = fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    if (quoted) {
      if (char === '"') {
        if (text[index + 1] === '"') {
          field += '"';
          index += 1;
        } else {
          quoted = false;
        }
      } else {
        field += char;
      }
    } else if (char === '"') {
      quoted = true;
    } else if (char === ',') {
      row.push(field);
      field = '';
    } else if (char === '\n') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
    } else {
      field += char;
    }
  }
  if (field.length > 0 || row.length > 0) {
    row.push(field);
    rows.push(row);
  }
  const [headers, ...body] = rows.filter((entry) => entry.some((value) => value !== ''));
  const records = body.map((entry) => Object.fromEntries(headers.map((header, index) => [header, entry[index] ?? ''])));
  return records;
}

const urls = parseCsv(urlsCsv);
const links = parseCsv(linksCsv);
if (urls.length === 0) {
  console.error(`no URLs in ${urlsCsv}`);
  process.exit(2);
}

const work = fs.mkdtempSync(path.join(os.tmpdir(), 'coqui-sf-fixture-'));
const sqlitePath = path.join(work, 'crawl.db');
const database = new DatabaseSync(sqlitePath);
database.exec(`
  create table urls (
    encoded_url text, response_code integer, response_msg text,
    blocked_by_robots_txt integer, content_type text, title_1 text,
    h1_1 text, num_h1 integer, word_count integer, crawl_depth integer,
    response_time_ms integer, page_size integer, is_internal integer,
    loaded_as_a_resource integer,
    meta_name_1 text, meta_content_1 text
  );
  create table links (
    link_type integer, src_id integer, dst_id integer,
    link_text text, nofollow integer, scope integer, element_path text
  );
  create table unique_urls (id integer primary key, encoded_url text);
`);

const insertUrl = database.prepare(`
  insert into urls (
    encoded_url, response_code, response_msg, blocked_by_robots_txt, content_type,
    title_1, h1_1, num_h1, word_count, crawl_depth, response_time_ms, page_size,
    is_internal, loaded_as_a_resource, meta_name_1, meta_content_1
  ) values (?, ?, ?, 0, ?, ?, ?, 1, ?, ?, ?, ?, 1, 0, 'description', ?)
`);
const insertUnique = database.prepare('insert into unique_urls (id, encoded_url) values (?, ?)');
const ids = new Map();
urls.forEach((row, index) => {
  const url = row.url;
  const title = row.title ?? '';
  const description = row.meta_description ?? row.description ?? '';
  const depth = row.depth ? Number(row.depth) : Math.min(index, 5);
  insertUrl.run(
    url,
    Number(row.status ?? 200),
    Number(row.status ?? 200) >= 400 ? 'Error' : 'OK',
    row.content_type ?? 'text/html; charset=utf-8',
    title,
    row.h1 ?? title,
    Number(row.word_count ?? 200),
    depth,
    Number(row.response_time_ms ?? 50),
    Number(row.size_bytes ?? 1000),
    description,
  );
  const id = index + 1;
  ids.set(url, id);
  insertUnique.run(id, url);
});

const hostOf = (value) => {
  try {
    return new URL(value).host;
  } catch {
    return '';
  }
};
const insertLink = database.prepare(
  'insert into links (link_type, src_id, dst_id, link_text, nofollow, scope, element_path) values (1, ?, ?, ?, 0, ?, ?)',
);
let imported = 0;
for (const row of links) {
  const from = ids.get(row.from_url);
  const to = ids.get(row.to_url);
  if (!from || !to) continue;
  const scope = hostOf(row.from_url) === hostOf(row.to_url) ? 1 : 0;
  insertLink.run(from, to, row.anchor ?? '', scope, '//body/a');
  imported += 1;
}
database.close();

const archiveRoot = path.join(work, 'archive');
fs.mkdirSync(path.join(archiveRoot, 'results_fixture'), { recursive: true });
fs.copyFileSync(sqlitePath, path.join(archiveRoot, 'results_fixture/sql'));
const zip = spawnSync('zip', ['-q', '-r', out, 'results_fixture'], { cwd: archiveRoot, encoding: 'utf8' });
if (zip.status !== 0) {
  console.error(zip.stderr || 'zip failed');
  process.exit(1);
}
fs.rmSync(work, { recursive: true, force: true });
console.log(`wrote ${out}: ${urls.length} URLs, ${imported} links`);
